package com.nexodb.ui;

import com.nexodb.tools.TeamWorkspaceService;import com.nexodb.util.AppSettings;import javax.swing.*;import javax.swing.border.EmptyBorder;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.time.ZoneId;import java.time.format.DateTimeFormatter;import java.util.*;import static com.nexodb.util.I18n.tr;

/** Migration review and privacy-safe team analytics dashboard. */
final class TeamWorkspacePanel extends JPanel {
 private final JTextField folder=new JTextField(34),reviewer=new JTextField(14),comment=new JTextField(24);private final DefaultTableModel reviewModel=model(new Object[]{tr("Migración"),tr("Estado"),tr("Revisor"),tr("Fecha"),tr("Comentario")}),activityModel=model(new Object[]{tr("Día"),tr("Acción"),tr("Cantidad")});private final JTable reviews=new JTable(reviewModel),activity=new JTable(activityModel);private final JLabel status=new JLabel(" ");private TeamWorkspaceService service;private java.util.List<TeamWorkspaceService.Review> rows=java.util.List.of();
 TeamWorkspacePanel(){super(new BorderLayout(6,6));setBorder(new EmptyBorder(8,8,8,8));folder.setText(AppSettings.get("team.workspace",""));reviewer.setText(AppSettings.get("team.reviewer",System.getProperty("user.name","")));JToolBar bar=new JToolBar();bar.setFloatable(false);bar.add(new JLabel(tr("Proyecto: ")));bar.add(folder);JButton browse=new JButton("…"),load=new JButton(tr("Abrir")),approve=new JButton(tr("Aprobar")),changes=new JButton(tr("Solicitar cambios")),export=new JButton(tr("Exportar informe…"));bar.add(browse);bar.add(load);bar.addSeparator();bar.add(new JLabel(tr("Revisor: ")));bar.add(reviewer);bar.add(new JLabel(tr(" Comentario: ")));bar.add(comment);bar.add(approve);bar.add(changes);bar.add(export);add(bar,BorderLayout.NORTH);reviews.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);reviews.setAutoCreateRowSorter(true);activity.setAutoCreateRowSorter(true);JTabbedPane tabs=new JTabbedPane();tabs.addTab(tr("Revisión de migraciones"),new JScrollPane(reviews));tabs.addTab(tr("Analítica del equipo"),new JScrollPane(activity));add(tabs);add(status,BorderLayout.SOUTH);browse.addActionListener(e->{JFileChooser chooser=new JFileChooser();chooser.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);if(chooser.showOpenDialog(DialogPosition.owner(this))==JFileChooser.APPROVE_OPTION)folder.setText(chooser.getSelectedFile().getAbsolutePath());});load.addActionListener(e->load());approve.addActionListener(e->review(TeamWorkspaceService.Decision.APPROVED));changes.addActionListener(e->review(TeamWorkspaceService.Decision.CHANGES_REQUESTED));export.addActionListener(e->export());if(!folder.getText().isBlank())load();}
 private void load(){try{service=new TeamWorkspaceService(Path.of(folder.getText()));AppSettings.put("team.workspace",service.root().toString());rows=service.migrationReviews();reviewModel.setRowCount(0);DateTimeFormatter date=DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm").withZone(ZoneId.systemDefault());for(var row:rows)reviewModel.addRow(new Object[]{row.file(),row.decision(),row.reviewer(),row.time().equals(java.time.Instant.EPOCH)?"":date.format(row.time()),row.comment()});activityModel.setRowCount(0);for(var item:service.activity())activityModel.addRow(new Object[]{item.day(),item.action(),item.count()});long approved=rows.stream().filter(r->r.decision()==TeamWorkspaceService.Decision.APPROVED).count();status.setText(rows.size()+tr(" migraciones · ")+approved+tr(" aprobadas · no se guardan SQL, datos ni credenciales"));}catch(Exception error){status.setText(message(error));}}
 private void review(TeamWorkspaceService.Decision decision){int selected=reviews.getSelectedRow();if(service==null||selected<0)return;int model=reviews.convertRowIndexToModel(selected);var row=rows.get(model);try{service.review(row.file(),row.checksum(),decision,reviewer.getText(),comment.getText());AppSettings.put("team.reviewer",reviewer.getText());load();}catch(Exception error){JOptionPane.showMessageDialog(DialogPosition.owner(this),message(error),tr("Revisión"),JOptionPane.ERROR_MESSAGE);}}
 private void export(){if(service==null)return;JFileChooser chooser=new JFileChooser();chooser.setSelectedFile(new java.io.File("estado-proyecto.md"));if(chooser.showSaveDialog(DialogPosition.owner(this))!=JFileChooser.APPROVE_OPTION)return;try{Files.writeString(chooser.getSelectedFile().toPath(),service.report(),StandardCharsets.UTF_8);status.setText(tr("Informe exportado: ")+chooser.getSelectedFile().getName());}catch(Exception error){JOptionPane.showMessageDialog(DialogPosition.owner(this),message(error));}}
 private static DefaultTableModel model(Object[] columns){return new DefaultTableModel(columns,0){public boolean isCellEditable(int r,int c){return false;}};}private static String message(Throwable error){while(error.getCause()!=null)error=error.getCause();return Objects.toString(error.getMessage(),error.getClass().getSimpleName());}
}
